import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.BLIJt2m0.js";const m=JSON.parse('{"title":"Backlog","description":"","frontmatter":{},"headers":[],"relativePath":"backlog.md","filePath":"backlog.md"}'),r={name:"backlog.md"};function l(s,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="backlog" tabindex="-1">Backlog <a class="header-anchor" href="#backlog" aria-label="Permalink to &quot;Backlog&quot;">​</a></h1><h2 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to &quot;Priority&quot;">​</a></h2><ul><li>Ensure their is no memory leak (since their is a lot of effect that are used, I do not know how the &quot;unsubscribe&quot; works as for observables)</li><li>A package that does not use the NgRx SignalStore &amp; Server State Store (it will come together) <ul><li>A way for query to be updated by other query result</li></ul></li><li>Infinite pagination/query (the a strategy to invalidate the cache as tanstackQuery does)</li><li>Why the globalQueries does not propose the autocompletion (I may not do that if I find a better approach with the Server State Store, that will replace it)</li><li><code>fallbackUpdate</code> to help to set the query state when a mutation failed (useful if their is an optimistic update) (I would like to propose the <code>lastSuccessfulValue</code> but it is not simple, because their is cases where multiples mutations can be trigger in parallel).</li><li>When <code>signalStore events</code> will be stable, the <code>rxQuery/rxMutation...</code> will accepts an event as params source, the property may be named <code>onEvent: event</code></li><li>Adding <code>insertUxLoader</code>, as it may avoid some flaky screen/loader. It is something that can easily improve the UX and the is a fundamental value of this lib</li><li>Propose a dedicated utility for handling update from <code>websocket</code></li></ul><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><ul><li>A page that compare Angular TanStackQuery and other solutions with @ng-query</li><li>Improve the insertObservables (to help to know when a new resource is created, and when is it reset/deleted) (their is maybe a memory leak to check)</li><li>Add a more complex example named &quot;Pokemon&quot; based on queryById / mutationById</li><li>Add property <code>reset</code> / <code>resetResource</code> for <code>ById</code> to help to remove/clean some resource that are no more needed (in pagination, it may be used to clean some not valid pagination)</li><li>Add more doc, specially when hovering the function, to show an example on how it should be implemented</li><li>Add doc for llm</li><li>Handle specific case when a mutation is trigger and some queries should react to it. But the mutation may be abort by the user who close the browser, or a bad connection... In this case, the idea may to force the cached queries to reload</li><li>When a query is pluggable, I would like to improve how it is bind to a component to help to deal with more complex case</li><li>Check if queries still needs runOnInjectionContext &amp; injector (internal)</li><li>Create a withRxMutation only based on observables</li><li>Add queries options <code>interval</code> to reload queries, refresh when windows focus ...</li><li>Improve the localStorePersister to remove expired cached queries when init</li><li>Maybe creating a proxy to access to queryById resources, like <code>userQueryById[&quot;1&quot;].status()</code> instead of <code>userQueryById()[&quot;1&quot;]?.status()</code></li></ul>',5)])])}const p=t(r,[["render",l]]);export{m as __pageData,p as default};
